//! Owned Rust builders over the CUI bridge. All operations stay on the creating thread.
use std::{
    cell::RefCell,
    collections::HashMap,
    ffi::{c_char, c_void, CString},
    marker::PhantomData,
    rc::Rc,
};

#[repr(C)]
#[derive(Clone, Copy, Default, Debug, PartialEq, Eq, Hash)]
struct RawNode {
    slot: u32,
    generation: u32,
}
#[repr(C)]
struct ChartDatumRaw {
    label_utf8: *const c_char,
    value: f64,
}
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ChartKind {
    Line = 0,
    Area = 1,
    Bar = 2,
    Pie = 3,
}
#[repr(C)]
#[derive(Clone, Copy, Default, Debug, PartialEq, Eq)]
pub struct Date {
    pub year: i32,
    pub month: i32,
    pub day: i32,
}
#[repr(C)]
#[derive(Clone, Copy, Default, Debug, PartialEq, Eq)]
pub struct Time {
    pub hour: u32,
    pub minute: u32,
    pub second: u32,
}
#[repr(C)]
#[derive(Clone, Copy, Default, Debug)]
pub struct Rect {
    pub x: f32,
    pub y: f32,
    pub width: f32,
    pub height: f32,
}
#[repr(C)]
#[derive(Clone, Copy, Default, Debug, PartialEq)]
pub struct PlotPoint {
    pub x: f64,
    pub y: f64,
}
#[repr(C)]
struct Options {
    struct_size: u32,
    abi_version: u32,
    backend: u32,
    max_nodes: u32,
    max_events: u32,
    width: f32,
    height: f32,
    title: *const c_char,
    font: *const c_char,
}
#[repr(C)]
#[derive(Clone, Copy, Default)]
struct EventEx {
    kind: u32,
    node: RawNode,
