            font: font.as_ref().map_or(std::ptr::null(), |x| x.as_ptr()),
        };
        let mut status = 0;
        let raw = unsafe { cui_bridge_create(&o, &mut status) };
        if raw.is_null() {
            return Err(Error(status));
        }
        let id = NEXT_ID.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
