        if (a->narrow)
            a->mobile_sidebar = !a->mobile_sidebar;
        else
            a->desktop_sidebar = !a->desktop_sidebar;
    }
    text(ui, a->narrow ? "Northstar" : pages[a->page], 16, t->text, true);
    spacer(ui);
