    text(ui, "Simple plans for teams of every size. Pick a fit and keep creating.", 14, t->muted,
         false);
    cui_begin_box(ui, 39, (cui_box){.width = -1, .row = width >= 720, .gap = 16});
    for (int i = 0; i < 3; ++i)
