    cui_rect account = cui_bounds(ui, APP_ACCOUNT);
    assert(account.x >= 0 && account.x + account.w <= width);
    click(APP_ACCOUNT);
    key(CUI_KEY_END, 0);
    key(CUI_KEY_ENTER, 0);
    frame();
    assert(!composed_app_snapshot(app).logged_in && counts.sessions == 4);
    click(APP_MENU);
    assert(composed_app_snapshot(app).sidebar_visible);
