            for (size_t i = 0; i < sizeof ids / sizeof ids[0]; ++i) {
                cui_rect b = cui_bounds(ui, ids[i]);
                if (b.w > 0 && b.h > 0)
                    printf("bound id=%u x=%.0f y=%.0f\n", (unsigned)ids[i], b.x + b.w / 2,
