}
static cui_speech_error start(void *user, speech_recognizer_endpoint *e, bool on_device,
                              void **out) {
    fixture *f = user;
    CHECK(on_device && pthread_equal(pthread_self(), f->owner));
    f->starts++;
    cui_speech_error error = operation(f, e, out);
    if (f->synchronous)
