    CHECK(!speech_recognizer_endpoint_authorized(f.late[0], SPEECH_AUTH_GRANTED));
    CHECK(f.wakes == wakes);
    release_late(&f);

    init(&f);
    f.status.authorization = SPEECH_AUTH_DENIED;
    CHECK(speech_recognizer_host_prepare(f.host) == CUI_SPEECH_PERMISSION && !f.authorizations);
    drop(&f);
