}
#ifdef CUI_TYPOGRAPHY_NATIVE
cui_font *typography_example_font(const char *body, const char *heading, const char *heading_bold,
                                  const char *body_italic, const char *code) {
    cui_font *font = cui_font_open(body);
    if (!font)
        return NULL;
    if (!cui_font_register_style(font, (cui_text_style){.family = TYPOGRAPHY_BODY_FAMILY}, body) ||
        !cui_font_register_style(font, (cui_text_style){.family = TYPOGRAPHY_HEADING_FAMILY},
                                 heading) ||
        !cui_font_register_style(
            font,
            (cui_text_style){.family = TYPOGRAPHY_HEADING_FAMILY, .weight = CUI_TEXT_WEIGHT_BOLD},
            heading_bold) ||
        !cui_font_register_style(font,
                                 (cui_text_style){.family = TYPOGRAPHY_BODY_FAMILY, .italic = true},
                                 body_italic) ||
        !cui_font_register_style(
            font, (cui_text_style){.family = TYPOGRAPHY_CODE_FAMILY, .monospace = true}, code)) {
        cui_font_close(font);
