        return VIDEO_AUDIO_AGAIN;
    *first = s->cursor;
    *frames = capacity;
    for (size_t i = 0; i < capacity; i++) {
        pcm[i * 2] = .25f;
        pcm[i * 2 + 1] = -.25f;
    }
