typedef enum {
    CUI_CHART_RADAR_TOOLTIP_TITLE_LEGACY,
    CUI_CHART_RADAR_TOOLTIP_TITLE_SOURCE_LABEL
} cui_chart_radar_tooltip_title_mode;
typedef struct {
    cui_str label;
