    cui_design_size design_size;                        /* INHERIT preserves legacy metrics. */
} cui_speech_button_options;
bool cui_speech_button(cui_context *, cui_id, const cui_theme *, cui_speech_state *,
                       cui_speech_button_options, double now);
typedef struct {
