/* A host picker supplies opaque sRGB bytes; the controlled model preserves alpha. */
int gallery_screen_color(unsigned rgb) {
    if (rgb > 0xffffffu)
        return 0;
    chosen_color.r = (uint8_t)(rgb >> 16);
    chosen_color.g = (uint8_t)(rgb >> 8);
    chosen_color.b = (uint8_t)rgb;
    return 1;
}
